effect.shader:

void main() {
    highp mat3 rgb2yuv = mat3(
         0.299,     0.587,    0.114,
        -0.14713,  -0.28886,  0.436,
         0.615,    -0.51499, -0.10001
    );
    vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
    vec3 yuv = texColor.rgb * rgb2yuv;

    float distance = 1 - yuv.g;
    if(!onlyCoarse) {
        distance += (yuv.u + yuv.v)/2/255;
    }
    distance *= 5.0;

    float lum = clamp((distance - clipLow) / (clipHigh - clipLow), 0.0,1.0);
    gl_FragColor = vec4(lum, lum, lum, 1.0);
}
